		feeReserve: maker ? 0 : base.feeReserve,
		admissionFeeReserve: route === "U" ? 0 : base.feeReserve,
		minOdds: route === "U" ? 1 / signal.limit_all_in : route === "T45R2" ? 1.4 : 1.5,
		maxEntryAgeMs: route === "U" ? signal.checkpoint_seconds * 1e3 + 5e3 : 6e4,
