//#region services/v12-executor/market-source.ts
function marketSource(get, now, sleep, ticker, target, side, p, log) {
	const quote = async () => {
		const started = now();
		return readBook(await get(`/trade-api/v2/markets/${encodeURIComponent(ticker)}/orderbook`), side, started, now());
	};
	const ready = async () => {
		let lastError = "NO_MARKET";
		let polls = 0;
		while (now() - target <= p.maxEntryAgeMs) {
			polls++;
			const started = now();
			try {
				const [meta, q] = await Promise.all([get(`/trade-api/v2/markets/${encodeURIComponent(ticker)}`), quote()]);
				validateMarket(meta?.market ?? meta, ticker, target, now());
				if (now() - q.requestStartedAt > p.quoteMaxAgeMs) throw new Error("STALE_ORDERBOOK");
				log({
					type: "market_source_ready",
					polls,
					at: now(),
					elapsed_ms: now() - started
				});
				return q;
			} catch (e) {
				lastError = String(e);
				if (e?.retryAfterMs || /IDENTITY_MISMATCH|WINDOW_MISMATCH|ALREADY_RESOLVED/.test(lastError)) throw e;
				if (polls === 1 || polls % 10 === 0) log({
					type: "market_source_wait",
					polls,
					at: now(),
					error: lastError
				});
				await sleep(p.pollMs);
			}
		}
		throw new Error(`ENTRY_DEADLINE:${lastError}`);
	};
	return {
		quote,
		ready
	};
}
